-- Live-row unique rules.
CREATE UNIQUE INDEX "accounts_live_name_key" ON "construction_finance"."accounts" ("workspace_id", lower("name")) WHERE "deleted_at" IS NULL;
CREATE UNIQUE INDEX "accounts_live_primary_key" ON "construction_finance"."accounts" ("workspace_id") WHERE "is_primary" AND "deleted_at" IS NULL;
CREATE UNIQUE INDEX "accounts_live_holder_key" ON "construction_finance"."accounts" ("workspace_id", "holder_member_id") WHERE "kind" = 'petty_cash' AND "deleted_at" IS NULL;
CREATE UNIQUE INDEX "payment_categories_live_name_key" ON "construction_finance"."payment_categories" ("workspace_id", lower("name")) WHERE "deleted_at" IS NULL;
CREATE UNIQUE INDEX "other_parties_live_name_key" ON "construction_finance"."other_parties" ("workspace_id", lower("name")) WHERE "deleted_at" IS NULL;
CREATE UNIQUE INDEX "transactions_live_number_key" ON "construction_finance"."transactions" ("workspace_id", "number") WHERE "deleted_at" IS NULL;
CREATE UNIQUE INDEX "account_transfers_live_number_key" ON "construction_finance"."account_transfers" ("workspace_id", "number") WHERE "deleted_at" IS NULL;
CREATE UNIQUE INDEX "petty_cash_vouchers_live_number_key" ON "construction_finance"."petty_cash_vouchers" ("workspace_id", "number") WHERE "deleted_at" IS NULL;
CREATE UNIQUE INDEX "other_expenses_live_number_key" ON "construction_finance"."other_expenses" ("workspace_id", "number") WHERE "deleted_at" IS NULL;
CREATE UNIQUE INDEX "party_payments_live_number_key" ON "construction_finance"."party_payments" ("workspace_id", "number") WHERE "deleted_at" IS NULL;
CREATE UNIQUE INDEX "party_openings_live_key" ON "construction_finance"."party_openings" ("workspace_id", "party_type", "party_id", coalesce("project_id", "store_id")) WHERE "deleted_at" IS NULL;
-- A bill's number is unique per party; a sales invoice's per Company.
CREATE UNIQUE INDEX "invoices_live_payable_number_key" ON "construction_finance"."invoices" ("workspace_id", "party_type", "party_id", lower("invoice_number")) WHERE "direction" = 'payable' AND "deleted_at" IS NULL;
CREATE UNIQUE INDEX "invoices_live_receivable_number_key" ON "construction_finance"."invoices" ("workspace_id", "invoice_number") WHERE "direction" = 'receivable' AND "deleted_at" IS NULL;
-- A GRN belongs to at most one live invoice (CM-0017 §13).
CREATE UNIQUE INDEX "invoice_goods_receipts_live_grn_key" ON "construction_finance"."invoice_goods_receipts" ("goods_receipt_id") WHERE "deleted_at" IS NULL;
-- One open settlement request per invoice.
CREATE UNIQUE INDEX "settlements_live_pending_key" ON "construction_finance"."settlements" ("invoice_id") WHERE "approval_status" = 'pending' AND "deleted_at" IS NULL;

-- Accounts.
ALTER TABLE "construction_finance"."accounts" ADD CONSTRAINT "accounts_kind_check" CHECK (
  ("kind" = 'petty_cash' AND "holder_member_id" IS NOT NULL AND NOT "is_primary")
  OR ("kind" <> 'petty_cash' AND "holder_member_id" IS NULL)
);
ALTER TABLE "construction_finance"."accounts" ADD CONSTRAINT "accounts_bank_fields_check" CHECK (
  "kind" = 'bank' OR ("bank_name" IS NULL AND "account_number" IS NULL AND "ifsc" IS NULL AND "branch" IS NULL)
);
ALTER TABLE "construction_finance"."accounts" ADD CONSTRAINT "accounts_ifsc_check" CHECK ("ifsc" IS NULL OR "ifsc" ~ '^[A-Z]{4}0[A-Z0-9]{6}$');

-- Ledgers: no zero entries; an original entry's sign follows its kind (a
-- reversal carries the opposite sign).
ALTER TABLE "construction_finance"."account_entries" ADD CONSTRAINT "account_entries_amount_check" CHECK (
  "amount" <> 0
  AND (
    "reverses_entry_id" IS NOT NULL
    OR "kind" = 'opening'
    OR ("kind" IN ('receipt', 'transfer_in') AND "amount" > 0)
    OR ("kind" IN ('payment', 'transfer_out') AND "amount" < 0)
  )
);
ALTER TABLE "construction_finance"."party_entries" ADD CONSTRAINT "party_entries_amount_check" CHECK (
  "amount" <> 0
  AND (
    "reverses_entry_id" IS NOT NULL
    OR "kind" IN ('opening', 'write_off')
    OR ("kind" IN ('invoice', 'receipt') AND "amount" > 0)
    OR ("kind" IN ('sales_invoice', 'payment', 'tds') AND "amount" < 0)
  )
);
ALTER TABLE "construction_finance"."party_entries" ADD CONSTRAINT "party_entries_place_check" CHECK ("project_id" IS NULL OR "store_id" IS NULL);

-- Transactions and transfers.
ALTER TABLE "construction_finance"."transactions" ADD CONSTRAINT "transactions_figures_check" CHECK (
  "amount" > 0
  AND ("project_id" IS NULL OR "store_id" IS NULL)
  AND ("mode" <> 'cheque' OR "cheque_number" IS NOT NULL)
  AND ("mode" NOT IN ('online', 'upi') OR "reference" IS NOT NULL)
  AND ("counterparty_kind" IS NOT NULL OR "counterparty_id" IS NULL)
);
ALTER TABLE "construction_finance"."transactions" ADD CONSTRAINT "transactions_rejection_check" CHECK ("approval_status" <> 'rejected' OR "reject_reason" IS NOT NULL);
ALTER TABLE "construction_finance"."account_transfers" ADD CONSTRAINT "account_transfers_figures_check" CHECK ("amount" > 0 AND "from_account_id" <> "to_account_id");
ALTER TABLE "construction_finance"."account_transfers" ADD CONSTRAINT "account_transfers_rejection_check" CHECK ("approval_status" <> 'rejected' OR "reject_reason" IS NOT NULL);

-- Petty-cash vouchers.
ALTER TABLE "construction_finance"."petty_cash_vouchers" ADD CONSTRAINT "petty_cash_vouchers_figures_check" CHECK (
  "amount" > 0
  AND (
    ("voucher_type" = 'transfer' AND "to_account_id" IS NOT NULL AND "to_account_id" <> "account_id")
    OR ("voucher_type" <> 'transfer' AND "to_account_id" IS NULL AND "payment_category_id" IS NOT NULL)
  )
  AND ("counterparty_kind" IS NOT NULL OR "counterparty_id" IS NULL)
);
ALTER TABLE "construction_finance"."petty_cash_vouchers" ADD CONSTRAINT "petty_cash_vouchers_rejection_check" CHECK ("approval_status" <> 'rejected' OR "reject_reason" IS NOT NULL);

-- Other Expenses.
ALTER TABLE "construction_finance"."other_expenses" ADD CONSTRAINT "other_expenses_figures_check" CHECK (
  "amount" > 0
  AND ("mode" <> 'cheque' OR "reference" IS NOT NULL)
  AND ("mode" NOT IN ('online', 'upi') OR "reference" IS NOT NULL)
);
ALTER TABLE "construction_finance"."other_expenses" ADD CONSTRAINT "other_expenses_rejection_check" CHECK ("approval_status" <> 'rejected' OR "reject_reason" IS NOT NULL);

-- Party openings, invoices, payments, allocations, settlements.
ALTER TABLE "construction_finance"."party_openings" ADD CONSTRAINT "party_openings_figures_check" CHECK (
  "amount" <> 0 AND (("project_id" IS NULL) <> ("store_id" IS NULL))
  AND ("store_id" IS NULL OR "party_type" = 'supplier')
);
ALTER TABLE "construction_finance"."invoices" ADD CONSTRAINT "invoices_figures_check" CHECK (
  "amount" > 0
  AND (("project_id" IS NULL) <> ("store_id" IS NULL))
  AND ("store_id" IS NULL OR "party_type" = 'supplier')
  AND ("direction" = 'payable' OR "party_type" = 'other_party')
  AND ("origin" = 'manual' OR "party_type" = 'supplier')
  AND ("department_id" IS NULL OR "party_type" = 'contractor')
  AND ("taxable_amount" IS NULL OR "taxable_amount" >= 0)
  AND ("gst_amount" IS NULL OR "gst_amount" >= 0)
  AND ("due_date" IS NULL OR "due_date" >= "invoice_date")
);
ALTER TABLE "construction_finance"."party_payments" ADD CONSTRAINT "party_payments_figures_check" CHECK (
  "amount" > 0
  AND (("project_id" IS NULL) <> ("store_id" IS NULL))
  AND ("store_id" IS NULL OR "party_type" = 'supplier')
  AND ("direction" = 'out' OR "party_type" = 'other_party')
  AND ("mode" <> 'cheque' OR "cheque_number" IS NOT NULL)
  AND ("mode" NOT IN ('online', 'upi') OR "reference" IS NOT NULL)
);
ALTER TABLE "construction_finance"."party_payments" ADD CONSTRAINT "party_payments_tds_check" CHECK (
  "tds_amount" >= 0
  AND ("party_type" = 'contractor' OR ("tds_amount" = 0 AND "tds_section" IS NULL))
  AND ("tds_amount" = 0 OR ("tds_section" IS NOT NULL AND "tds_base" IS NOT NULL AND "tds_rate" IS NOT NULL))
  AND ("tds_rate" IS NULL OR ("tds_rate" >= 0 AND "tds_rate" <= 100))
  AND ("tds_suggested" IS NULL OR "tds_suggested" = "tds_amount" OR "tds_override_reason" IS NOT NULL)
);
ALTER TABLE "construction_finance"."payment_allocations" ADD CONSTRAINT "payment_allocations_amount_check" CHECK ("amount" > 0);
ALTER TABLE "construction_finance"."settlements" ADD CONSTRAINT "settlements_amount_check" CHECK ("amount" > 0);
ALTER TABLE "construction_finance"."settlements" ADD CONSTRAINT "settlements_rejection_check" CHECK ("approval_status" <> 'rejected' OR "reject_reason" IS NOT NULL);

-- TDS rates.
ALTER TABLE "construction_finance"."statutory_tds_rates" ADD CONSTRAINT "statutory_tds_rates_figures_check" CHECK (
  "rate" >= 0 AND "rate" <= 100 AND "single_threshold" >= 0 AND "aggregate_threshold" >= 0
);
